package modulo1;

public class ExercicioSecao4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int numero = 10;
		System.out.println("O número é: " +(numero) );
		System.out.println("Soma com 5: " +(numero + 5) );
		System.out.println("Multiplicação por 2:" +(numero * 2));
		System.out.println("Subtração por 8:" +(numero - 8) );
	}

}
